require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/layout.php';require_once __DIR__.'/../app/local_assistant_booking_v1040.php';$me=current_user();if(!$me||!(has_permission('settings.manage',$me)||has_permission('tenants.manage',$me))){http_response_code(403);exit('Forbidden');}$uid=(int)$me['id'];$tid=sk1040_tid();$flash='';$error='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$a=(string)($_POST['action']??'');if($a==='settings'){$fields=['assistant','booking','guest_booking','provider_inbox','homepage_section','search_logging','booking_reminders'];$vals=[];foreach($fields as $f)$vals[$f]=(isset($_POST[$f.'_enabled'])?1:0);$q=db()->prepare('INSERT INTO local_assistant_settings_v1040(tenant_id,assistant_enabled,booking_enabled,guest_booking_enabled,provider_inbox_enabled,homepage_section_enabled,search_logging_enabled,booking_reminders_enabled,max_results,booking_min_notice_minutes,updated_by,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE assistant_enabled=VALUES(assistant_enabled),booking_enabled=VALUES(booking_enabled),guest_booking_enabled=VALUES(guest_booking_enabled),provider_inbox_enabled=VALUES(provider_inbox_enabled),homepage_section_enabled=VALUES(homepage_section_enabled),search_logging_enabled=VALUES(search_logging_enabled),booking_reminders_enabled=VALUES(booking_reminders_enabled),max_results=VALUES(max_results),booking_min_notice_minutes=VALUES(booking_min_notice_minutes),updated_by=VALUES(updated_by),updated_at=NOW()');$q->execute([$tid,$vals['assistant'],$vals['booking'],$vals['guest_booking'],$vals['provider_inbox'],$vals['homepage_section'],$vals['search_logging'],$vals['booking_reminders'],max(6,min(40,(int)($_POST['max_results']??18))),max(0,min(1440,(int)($_POST['booking_min_notice_minutes']??30))),$uid]);$flash='Settings saved.';}elseif($a==='suggestion_add'){db()->prepare('INSERT INTO local_assistant_suggestions_v1040(tenant_id,label,query_text,icon,sort_order,enabled,created_at,updated_at) VALUES(?,?,?,?,?,1,NOW(),NOW())')->execute([$tid,mb_substr(trim((string)$_POST['label']),0,120),mb_substr(trim((string)$_POST['query_text']),0,250),mb_substr(trim((string)($_POST['icon']??'•')),0,16),(int)($_POST['sort_order']??100)]);$flash='Suggestion added.';}elseif($a==='suggestion_delete'){db()->prepare('DELETE FROM local_assistant_suggestions_v1040 WHERE tenant_id=? AND id=?')->execute([$tid,(int)$_POST['id']]);$flash='Suggestion removed.';}elseif($a==='booking_status'){ $id=(int)$_POST['id'];$st=(string)$_POST['status'];if(!in_array($st,['pending','confirmed','reschedule_requested','completed','rejected','cancelled'],true))throw new RuntimeException('Invalid status.');db()->prepare('UPDATE unified_bookings_v1040 SET status=?,provider_note=?,updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([$st,mb_substr(trim((string)($_POST['provider_note']??'')),0,800),$tid,$id]);sk1040_log_status($id,$st,'Updated by admin',$uid);$flash='Booking updated.';}}}catch(Throwable $e){$error=$e->getMessage();}$cfg=sk1040_settings(true);$stats=sk1040_stats();$sugs=sk1040_suggestions(50);$bookings=[];$searches=[];try{$q=db()->prepare('SELECT * FROM unified_bookings_v1040 WHERE tenant_id=? ORDER BY id DESC LIMIT 80');$q->execute([$tid]);$bookings=$q->fetchAll()?:[];}catch(Throwable $e){}try{$q=db()->prepare('SELECT query_text,result_count,created_at FROM local_assistant_searches_v1040 WHERE tenant_id=? ORDER BY id DESC LIMIT 30');$q->execute([$tid]);$searches=$q->fetchAll()?:[];}catch(Throwable $e){}page_start('Assistant & Booking',true);
?><link rel="stylesheet" href="/assets/admin-local-assistant-v1040.css?v=1040"><div class="lab-admin"><section class="lab-hero"><div><span>SHAHKOTPK v10.4.0 · CUSTOMER EXPERIENCE</span><h2>Smart Local Assistant & Unified Booking Center</h2><p>Help visitors discover live local listings in natural language and turn discovery into booking requests that providers can confirm from one inbox.</p></div><div class="hero-actions"><a href="/assistant-v1040.php" target="_blank">Open Assistant ↗</a><a href="/booking-inbox-v1040.php" target="_blank">Provider Inbox ↗</a></div></section><?php if($flash):?><div class="lab-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="lab-alert bad"><?=e($error)?></div><?php endif;?><div class="lab-stats"><article><small>SEARCHES TODAY</small><b><?=number_format($stats['searches_today'])?></b></article><article><small>PENDING BOOKINGS</small><b><?=number_format($stats['bookings_pending'])?></b></article><article><small>CONFIRMED</small><b><?=number_format($stats['bookings_confirmed'])?></b></article><article><small>TOTAL BOOKINGS</small><b><?=number_format($stats['bookings_total'])?></b></article></div><section class="lab-card"><h3>Feature controls</h3><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="settings"><div class="lab-toggles"><?php foreach(['assistant','booking','guest_booking','provider_inbox','homepage_section','search_logging','booking_reminders'] as $k):?><label><input type="checkbox" name="<?=$k?>_enabled" value="1" <?=!empty($cfg[$k.'_enabled'])?'checked':''?>> <?=e(ucwords(str_replace('_',' ',$k)))?></label><?php endforeach;?></div><div class="lab-form"><label>Max search results<input type="number" name="max_results" min="6" max="40" value="<?=(int)$cfg['max_results']?>"></label><label>Minimum booking notice (minutes)<input type="number" name="booking_min_notice_minutes" min="0" max="1440" value="<?=(int)$cfg['booking_min_notice_minutes']?>"></label></div><button>Save Settings</button></form></section><div class="lab-grid"><section class="lab-card"><h3>Assistant quick suggestions</h3><form method="post" class="lab-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="suggestion_add"><label>Label<input name="label" required></label><label>Search query<input name="query_text" required></label><label>Icon<input name="icon" value="•"></label><label>Order<input type="number" name="sort_order" value="100"></label><button>Add Suggestion</button></form><?php foreach($sugs as $s):?><div class="lab-row"><div><b><?=e((string)$s['icon'])?> <?=e((string)$s['label'])?></b><small><?=e((string)$s['query_text'])?></small></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="suggestion_delete"><input type="hidden" name="id" value="<?=(int)$s['id']?>"><button class="link danger">Delete</button></form></div><?php endforeach;?></section><section class="lab-card"><h3>Recent assistant searches</h3><?php foreach($searches as $s):?><div class="lab-row"><div><b><?=e((string)$s['query_text'])?></b><small><?=(int)$s['result_count']?> result(s) · <?=e(date('d M h:i A',strtotime((string)$s['created_at'])))?></small></div></div><?php endforeach;?><?php if(!$searches):?><p class="muted">No searches logged yet.</p><?php endif;?></section></div><section class="lab-card"><h3>Unified bookings</h3><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Customer</th><th>Date & Time</th><th>Status</th><th>Admin action</th></tr></thead><tbody><?php foreach($bookings as $b):?><tr><td><b><?=e((string)$b['booking_no'])?></b><small><?=e((string)$b['entity_type'])?> · <?=e((string)$b['entity_title'])?></small></td><td><?=e((string)$b['customer_name'])?><small><?=e((string)$b['customer_phone'])?></small></td><td><?=e(date('d M Y h:i A',strtotime((string)$b['requested_at'])))?></td><td><?=e((string)$b['status'])?></td><td><form method="post" class="inline"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="booking_status"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><select name="status"><?php foreach(['pending','confirmed','reschedule_requested','completed','rejected','cancelled'] as $st):?><option value="<?=$st?>" <?=$st===$b['status']?'selected':''?>><?=$st?></option><?php endforeach;?></select><input name="provider_note" value="<?=e((string)($b['provider_note']??''))?>" placeholder="Note"><button>Save</button></form></td></tr><?php endforeach;?><?php if(!$bookings):?><tr><td colspan="5">No bookings yet.</td></tr><?php endif;?></tbody></table></div></section><section class="lab-card"><h3>Booking reminders worker</h3><p>Run hourly from Cron Manager. It creates in-app reminders for confirmed bookings due in the next 24 hours.</p><code>php <?=e(dirname(__DIR__).'/cron/booking-reminders-v1040.php')?></code></section></div><?php require __DIR__.'/../app/end.php';?>
